def create_staff_roles(apps, schema_editor):
    Role = apps.get_model("accounts", "Role")
    RolePermission = apps.get_model("accounts", "RolePermission")
    for slug, name, order, perms in STAFF:
        role, _ = Role.objects.get_or_create(group=None, slug=slug, defaults={"name": name, "kind": "plateforme", "sort_order": order})
        for res, actions in perms.items():
            for act in actions:
                RolePermission.objects.get_or_create(role=role, resource=res, action=act)


def remove_staff_roles(apps, schema_editor):
    apps.get_model("accounts", "Role").objects.filter(group=None, slug__in=[s[0] for s in STAFF]).delete()


